((e,t)=>{e.behaviors.managerProjectsEvents={attach(n){t(`manager-projects-events`,`details[data-events-url]`,n).forEach(t=>{let n=t.querySelector(`.manager-projects__all-events-body`);if(!n)return;let r=n.innerHTML,i=!1;t.addEventListener(`toggle`,()=>{t.open&&!i&&(i=!0,n.setAttribute(`aria-busy`,`true`),n.textContent=e.t(`Loading…`),fetch(t.dataset.eventsUrl,{credentials:`same-origin`,headers:{Accept:`text/html`}}).then(e=>{if(!e.ok||e.redirected)throw Error(`Status ${e.status}`);return e.text()}).then(t=>{n.innerHTML=t,e.attachBehaviors(n)}).catch(()=>{i=!1,n.innerHTML=`<p class="manager-projects__events-note">${e.t(`The events could not be loaded.`)}</p>${r}`}).finally(()=>{n.removeAttribute(`aria-busy`)}))})})}}})(Drupal,once);